          "短信费",
          "年费",
          "利息",
          "账户管理费",
          "冲正",
          "测试"
        ]
      }
    },
    {
      "id": "op_5",
      "name": "GroupBy",
      "input_from": [
        "op_4"
      ],
      "output_alias": "df_bank_agg",
      "params": {
        "by": [
          "付款单位"
        ],
        "aggregations": {
          "贷方发生额": "sum"
        }
      }
    },
    {
      "id": "op_6",
      "name": "Merge",
      "input_from": [
        "op_5",
        "op_2"
      ],
      "output_alias": "df_merged",
      "params": {
        "how": "left",
        "left_on": [
          "付款单位"
        ],
        "right_on": [
          "缴费单位"
        ]
      }
    },
    {
      "id": "op_7",
      "name": "Diff",
      "input_from": [
        "op_6"
      ],
      "output_alias": "df_result",
      "params": {
        "col_a": "贷方发生额_sum",
        "col_b": "应收金额",
        "tolerance_pct": 0.0,
        "output_mode": "all"
      }
    },
    {
      "id": "op_8",
      "name": "ConditionCheck",
      "input_from": [
        "op_7"
      ],
      "output_alias": "df_risk",
      "params": {
        "rules": [
          {
            "column": "diff_amount",
            "operator": ">=",
            "value": 35000,
            "tag": "HIGH"
          }
        ],
        "default_tag": "LOW"
      }
    },
    {
      "id": "op_9",
      "name": "Export",
      "input_from": [
        "op_8"
      ],
      "params": {
        "filename": "社保回款与登记台账核对结果.xlsx"
      }
    }
  ],
  "context": {
    "tolerance_pct": 0.0,
    "noise_rules": [
      "手续费",
      "短信费",
      "年费",
      "利息"
    ],
    "high_diff_threshold": 35000
  },
  "risk_alerts": [
    {
      "level": "HIGH",
      "rule": "差额 ≥ 3.5万元的单位需人工重点复核"
    }
  ],
  "human_review_points": [
    "确认付款单位与缴费单位是否完全匹配，可能存在名称差异",
    "检查登记月份是否与银行流水日期匹配",
    "确认贷方发生额是否为社保回款，排除其他类型交易",
    "核实差异金额是否为合理未达账项或登记错误"
  ],
  "expected_outputs": [
    "输出核对结果表格，包含单位名称、银行回款金额、登记应收金额、差异金额、风险等级"
  ]
}
